	query := `
WITH effective (namespace, environment, version) AS (
	SELECT namespace, environment, MAX(version)
	FROM config_versions
	WHERE gray_tag IS NULL
	GROUP BY namespace, environment
)
SELECT v.namespace, v.environment, COALESCE(e.version, 0), i.value_json
FROM (SELECT DISTINCT namespace, environment FROM config_versions) AS v
LEFT JOIN effective AS e
  ON e.namespace = v.namespace AND e.environment = v.environment
LEFT JOIN config_items AS i
  ON i.namespace = v.namespace AND i.environment = v.environment
 AND i.version = e.version AND i.name = ?
 WHERE 1 = 1`
	args := []any{name}
	if namespace != "" {
		query += ` AND v.namespace = ?`
		args = append(args, namespace)
	}
	if environment != "" {
		query += ` AND v.environment = ?`
		args = append(args, environment)
	}
	query += ` ORDER BY v.namespace ASC, v.environment ASC`

	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("search effective item: %w", err)
	}
	defer rows.Close()
	results := []EffectiveItemScope{}
	for rows.Next() {
		var entry EffectiveItemScope
		var value sql.NullString
		if err := rows.Scan(&entry.Namespace, &entry.Environment, &entry.EffectiveVersion, &value); err != nil {
			return nil, fmt.Errorf("scan effective item: %w", err)
		}
		entry.HasValue = value.Valid
		entry.Value = value.String
		results = append(results, entry)
	}
	return results, rows.Err()
}

// HistoricalEffectiveVersion returns the newest full-release snapshot of a scope that was
// effective at the given point in time. Only versions with a created_at no later than asOf
// participate and gray releases (gray_tag IS NULL is required) never qualify. When several full
// releases share the creation second, the highest version number wins. It is one read-only query
// and creates no row. ErrNotFound means the scope had no full release at that point in time.
func (s *Store) HistoricalEffectiveVersion(ctx context.Context, namespace, environment string, asOf time.Time) (Version, error) {
	// Stored timestamps are UTC RFC3339 values truncated to the second; comparing the cutoff as
	// the same fixed-width string keeps versions created within the asOf second eligible.
	cutoff := asOf.UTC().Truncate(time.Second).Format(time.RFC3339)
	return s.queryVersion(ctx,
		`SELECT namespace, environment, version, gray_tag, rollback_of, promotion_of, created_at
		 FROM config_versions
		 WHERE namespace = ? AND environment = ? AND gray_tag IS NULL AND created_at <= ?
		 ORDER BY created_at DESC, version DESC
		 LIMIT 1`,
		namespace, environment, cutoff)
}

// EffectiveVersion returns the latest full-release version of a scope. Gray releases never
// become effective. 0 means no effective snapshot exists.
func (s *Store) EffectiveVersion(ctx context.Context, namespace, environment string) (int64, error) {
	var version int64
	err := s.db.QueryRowContext(ctx,
		`SELECT COALESCE(MAX(version), 0) FROM config_versions
		 WHERE namespace = ? AND environment = ? AND gray_tag IS NULL`,
		namespace, environment).Scan(&version)
	if err != nil {
		return 0, fmt.Errorf("effective version: %w", err)
	}
	return version, nil
}

func (s *Store) queryVersion(ctx context.Context, query string, args ...any) (Version, error) {
	row := s.db.QueryRowContext(ctx, query, args...)
	v, err := scanVersion(row)
	if errors.Is(err, sql.ErrNoRows) {
		return Version{}, ErrNotFound
	}
	return v, err
}

type rowScanner interface {
	Scan(dest ...any) error
}

func scanVersion(scanner rowScanner) (Version, error) {
	var v Version
	if err := scanner.Scan(&v.Namespace, &v.Environment, &v.Version, &v.GrayTag, &v.RollbackOf, &v.PromotionOf, &v.CreatedAt); err != nil {
		return Version{}, fmt.Errorf("scan version: %w", err)
	}
	return v, nil
}

