func TestVersionRecordsFiltersIntersectAndPaginate(t *testing.T) {
	_, handler := newTestRouter(t)
	publish(t, handler, "payments", "prod", "", map[string]any{"a": json.RawMessage("1")})
	publish(t, handler, "payments", "prod", "canary", map[string]any{"a": json.RawMessage("2")})
	rollback(t, handler, "payments", "prod", 1)
	publish(t, handler, "payments", "prod", "beta", map[string]any{"a": json.RawMessage("4")})
	postVersionAction(t, handler, "payments", "prod", 4, "promote")

	cases := []struct {
		name      string
		query     string
		matched   int
		effective []bool
		versions  []int64
	}{
		{"gray tag", "namespace=payments&environment=prod&grayTag=canary", 1, []bool{false}, []int64{2}},
		{"rollback of", "namespace=payments&environment=prod&rollbackOf=1", 1, []bool{false}, []int64{3}},
		{"effective true", "namespace=payments&environment=prod&effective=true", 1, []bool{true}, []int64{5}},
		{"effective false", "namespace=payments&environment=prod&effective=false", 4,
			[]bool{false, false, false, false}, []int64{1, 2, 3, 4}},
		{"gray and non-effective", "namespace=payments&environment=prod&grayTag=beta&effective=false",
			1, []bool{false}, []int64{4}},
		{"gray and effective", "namespace=payments&environment=prod&grayTag=beta&effective=true",
			0, nil, []int64{}},
		{"rollback and gray canary", "namespace=payments&environment=prod&rollbackOf=1&grayTag=canary",
			0, nil, []int64{}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			recorder := doRequest(t, handler, http.MethodGet, recordsPath(tc.query), nil)
			if recorder.Code != http.StatusOK {
				t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
			}
			body := decodeVersionRecords(t, recorder)
			if body.MatchedCount != tc.matched || !int64SlicesEqual(recordVersions(body.Versions), tc.versions) {
				t.Fatalf("body = %+v, want versions %v matched %d", body, tc.versions, tc.matched)
			}
			for i, wantEffective := range tc.effective {
				if body.Versions[i].Effective != wantEffective {
					t.Fatalf("version %d effective = %v, want %v", body.Versions[i].Version,
						body.Versions[i].Effective, wantEffective)
				}
			}
		})
	}
}

