func TestVersionRecordsListsScopeWithSnapshotsAndMetadata(t *testing.T) {
	_, handler := newTestRouter(t)
	setupRecordHistory(t, handler)

	recorder := doRequest(t, handler, http.MethodGet, scopedRecordsPath("payments", "prod"), nil)
	if recorder.Code != http.StatusOK {
		t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
	}
	body := decodeVersionRecords(t, recorder)
	if body.Namespace != "payments" || body.Environment != "prod" {
		t.Fatalf("scope = %s/%s", body.Namespace, body.Environment)
	}
	if body.MatchedCount != 5 || body.HasMore || body.NextAfterVersion != 5 {
		t.Fatalf("page = %+v", body)
	}
	if got := recordVersions(body); len(got) != 5 || got[0] != 1 || got[4] != 5 {
		t.Fatalf("versions = %v", got)
	}

	v1 := body.Versions[0]
	if v1.GrayTag != nil || v1.RollbackOf != nil || v1.PromotionOf != nil || !v1.Effective || v1.CreatedAt == "" {
		t.Fatalf("v1 metadata = %+v", v1)
	}
	v1Effective := false
	for _, record := range body.Versions {
		if record.Effective {
			if v1Effective || record.Version != 5 {
				t.Fatalf("only v5 must be effective, got %d", record.Version)
			}
			v1Effective = true
		}
	}
	if !v1Effective {
		t.Fatalf("v5 must be marked effective")
	}
	if tag := body.Versions[1].GrayTag; tag == nil || *tag != "canary" {
		t.Fatalf("v2 grayTag = %v", tag)
	}
	if body.Versions[2].RollbackOf == nil || *body.Versions[2].RollbackOf != 1 {
		t.Fatalf("v3 rollbackOf = %v", body.Versions[2].RollbackOf)
	}
	if tag := body.Versions[3].GrayTag; tag == nil || *tag != "beta" {
		t.Fatalf("v4 grayTag = %v", tag)
	}
	if body.Versions[4].PromotionOf == nil || *body.Versions[4].PromotionOf != 4 {
		t.Fatalf("v5 promotionOf = %v", body.Versions[4].PromotionOf)
	}
}

