func TestVersionRecordsPaginationWalksMatches(t *testing.T) {
	_, handler := newTestRouter(t)
	for i := 0; i < 5; i++ {
		publish(t, handler, "svc", "dev", "", map[string]any{"n": i})
	}

	var walked []int64
	after := ""
	for {
		recorder := doRequest(t, handler, http.MethodGet,
			recordsPath("namespace=svc&environment=dev&limit=2"+after), nil)
		if recorder.Code != http.StatusOK {
			t.Fatalf("status = %d body = %s", recorder.Code, recorder.Body.String())
		}
		body := decodeVersionRecords(t, recorder)
		if body.MatchedCount != 5 {
			t.Fatalf("matchedCount = %d, want 5", body.MatchedCount)
		}
		walked = append(walked, recordVersions(body)...)
		if !body.HasMore {
			break
		}
		after = "&afterVersion=" + jsonNumber(body.NextAfterVersion)
	}
	if want := []int64{1, 2, 3, 4, 5}; !int64SliceEqual(walked, want) {
		t.Fatalf("walked = %v, want %v", walked, want)
	}
}

